"""Bounded display geometry from provider evidence, never generated by the model."""
from __future__ import annotations

import math


def point(value) -> tuple[float, float] | None:
    try:
        values = value.split(",") if isinstance(value, str) else value
        if len(values) != 2:
            return None
        lng, lat = map(float, values)
        if math.isfinite(lng) and math.isfinite(lat) and -180 <= lng <= 180 and -85 <= lat <= 85:
            return lng, lat
    except (ValueError, TypeError, OverflowError):
        pass
    return None


def coordinate_text(value) -> str:
    parsed = point(value)
    if parsed is None:
        raise ValueError("路线坐标不合法")
    return ",".join(f"{number:.6f}".rstrip("0").rstrip(".") if number else "0" for number in parsed)


def sample_points(points: list, limit: int) -> list:
    if len(points) <= limit:
        return points
    return [points[round(index * (len(points) - 1) / (limit - 1))] for index in range(limit)]


def geometry_from_steps(steps: list) -> dict:
    points = []
    for step in steps:
        encoded = step.get("polyline")
        if not isinstance(encoded, str) or not encoded:
            return {}
        for token in encoded.split(";"):
            parsed = point(token)
            if parsed is None:
                return {}
            if not points or tuple(points[-1]) != parsed:
                points.append(list(parsed))
    if len(points) < 2:
        return {}
    return {"coordinates": sample_points(points, 1500), "coordinate_system": "GCJ-02",
            "source": "amap_route_steps", "sampled": len(points) > 1500}


def without_map_geometry(value):
    if isinstance(value, dict):
        # The prose answer describes the selected result; alternate paths belong to the map UI.
        return {key: without_map_geometry(item) for key, item in value.items() if key not in {"geometry", "alternatives"}}
    if isinstance(value, list):
        return [without_map_geometry(item) for item in value]
    return value
